export type IconName = keyof typeof PATHS

export function Icon({ name, size = 24, variant = "Linear", className }: { name: IconName; size?: number; variant?: Variant; className?: string }) {
  const entry = PATHS[name]
  if (!entry) return null
  const inner = variant === "Bold" ? entry.bold : entry.linear
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" className={className} dangerouslySetInnerHTML={{ __html: inner }} />
  )
}
